function findLeaders(arr) {
  const leaders = [arr[arr.length - 1]];
  let maxFromRight = arr[arr.length - 1];
  for (let i = arr.length - 2; i >= 0; i--) {
    if (arr[i] > maxFromRight) {
      maxFromRight = arr[i];
      leaders.unshift(arr[i]);
    }
  }
  return leaders;
}
